const t=k=>(dict[state.language]||dict.en)[k]||dict.en[k]||k;
const fmt=(d,opts={weekday:'short',day:'numeric',month:'short'})=>new Intl.DateTimeFormat(state.language==='mr'?'mr-IN':'en-IN',opts).format(new Date(d));
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),3600)}
const q=(id)=>document.getElementById(id);
async function init(){try{const d=await api('/api/session');state.user=d.user;if(state.user){state.language=state.user.language;await loadWorkspace();}render();}catch(e){renderAuth();}}
async function loadWorkspace(){const d=await api('/api/farms');state.farms=d.farms;state.farm=state.farms[0]||null;if(!state.farm)return;await Promise.all([loadWeather(),loadRecords()]);}
async function loadRecords(){if(!state.farm)return;const id=encodeURIComponent(state.farm.id);const [soil,seasons,obs,adv,checks,community]=await Promise.all([api(`/api/soil?farmId=${id}`),api(`/api/crops?farmId=${id}`),api(`/api/observations?farmId=${id}`),api(`/api/advisories?farmId=${id}`),api(`/api/disease-checks?farmId=${id}`),api('/api/community')]);state.soil=soil.tests;state.seasons=seasons.seasons;state.observations=obs.observations;state.advisories=adv.advisories;state.diseaseChecks=checks.checks;state.community=community;}
async function loadWeather(){state.weather=null;state.weatherError=null;try{state.weather=await api(`/api/weather?farmId=${encodeURIComponent(state.farm.id)}`);}catch(e){if(e.data?.browserFallback){try{const params=new URLSearchParams({latitude:String(state.farm.lat),longitude:String(state.farm.lon),current:'temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,wind_speed_10m_max',timezone:'Asia/Kolkata',forecast_days:'5'});const r=await fetch('https://api.open-meteo.com/v1/forecast?'+params);if(!r.ok)throw Error(`Forecast provider returned ${r.status}`);const raw=await r.json();state.weather={source:'Open-Meteo',sourceUrl:'https://open-meteo.com/en/docs',fetchedAt:new Date().toISOString(),validUntil:raw.daily.time.at(-1),timezone:raw.timezone,current:raw.current,daily:raw.daily.time.map((date,i)=>({date,max:raw.daily.temperature_2m_max[i],min:raw.daily.temperature_2m_min[i],rainProbability:raw.daily.precipitation_probability_max?.[i]??null,rain:raw.daily.precipitation_sum[i],wind:raw.daily.wind_speed_10m_max[i],code:raw.daily.weather_code[i]}))};}catch(fallbackError){state.weatherError=fallbackError.message;}}else state.weatherError=e.message;}}
function renderAuth(mode='register'){const app=q('app');app.innerHTML=`<main class="auth-wrap"><div class="auth-brand"><div class="brand-mark">✿</div><div><div class="brand-name">AgriSathi</div><div class="brand-tag">LOCAL FARM INTELLIGENCE · NASHIK PILOT</div></div></div><section class="auth-card"><h1>${t('createAccount')}</h1><p>${t('localAuth')} English + मराठी · Nashik, Maharashtra</p><form id="auth-form"><div class="field"><label>${t('name')}</label><input name="name" autocomplete="username" required maxlength="80" placeholder="e.g. Asha Patil"></div><div class="field"><label>${t('password')}</label><input name="password" type="password" minlength="10" autocomplete="new-password" required placeholder="10 or more characters"></div>${mode==='register'?`<div class="field"><label>Town / village within Nashik district</label><input name="location" value="Nashik" required maxlength="100"><small>We send this selected town to Open-Meteo geocoding for a town-center forecast; precise farm coordinates are not requested.</small></div><div class="field"><label>${t('experience')}</label><select name="farmerType"><option value="experienced">${t('experienced')}</option><option value="beginner">${t('beginner')}</option></select></div><div class="field"><label>${t('selectCrop')}</label><select name="crop"><option>Tomato</option><option>Grape</option></select></div><div class="field"><label>${t('language')}</label><select name="language"><option value="en">English</option><option value="mr">मराठी</option></select></div><button class="btn" type="submit">${t('register')} →</button>`:`<button class="btn" type="submit">${t('signIn')} →</button>`}</form><div class="auth-switch">${mode==='register'?t('haveAccount'):t('newHere')} <button class="text-button" id="auth-switch">${mode==='register'?t('signIn'):t('register')}</button></div><div class="banner info" style="margin-top:17px">Your farm details are saved in a local SQLite database on this computer. Create a memorable password to protect this workspace.</div></section></main>`;q('auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),payload=Object.fromEntries(f);try{if(mode==='register'){const g=await geocodePlace(payload.location);Object.assign(payload,{lat:g.latitude,lon:g.longitude,location:g.name});}const d=await api(mode==='register'?'/api/register':'/api/login',{method:'POST',body:JSON.stringify(payload)});state.user=d.user;state.language=d.user.language;await loadWorkspace();render();}catch(err){toast(err.message,true);}};q('auth-switch').onclick=()=>renderAuth(mode==='register'?'login':'register');}
async function geocodePlace(query){const p=new URLSearchParams({name:query,count:'8',language:'en',format:'json'});const r=await fetch('https://geocoding-api.open-meteo.com/v1/search?'+p);if(!r.ok)throw Error(`Location lookup failed (${r.status}). Try again.`);const d=await r.json();const x=(d.results||[]).find(v=>v.country_code==='IN'&&/maharashtra/i.test(v.admin1||'')&&/nashik/i.test(v.admin2||''));if(!x)throw Error('No matching town in Nashik district was found. Try the town or village name, or enter Nashik.');return {latitude:x.latitude,longitude:x.longitude,name:x.name};}
function render(){if(!state.user)return renderAuth();document.documentElement.lang=state.language==='mr'?'mr':'en';const app=q('app');app.innerHTML=`<div class="app"><aside class="sidebar ${state.sidebar?'open':''}"><div class="brand"><div class="brand-mark">✿</div><div><div class="brand-name">AgriSathi</div><div class="brand-tag">LOCAL FARM INTELLIGENCE</div></div></div><div class="nav-label">${t('farmIntel')}</div><nav class="nav">${[['dashboard','◫','overview'],['advisory','✳','advisory'],['planner','⌘','planner'],['disease','◉','disease'],['assistant','✦','assistant']].map(navItem).join('')}</nav><div class="nav-label">${t('workspace')}</div><nav class="nav">${[['soil','▤','soil'],['community','◎','community'],['history','⌑','history'],['sources','↗','sources']].map(navItem).join('')}</nav><div class="side-bottom"><div class="region-box"><div class="region-label">${t('pilot')}</div><div class="region-place">⌖ &nbsp;${esc(state.farm?.location_name||'Nashik')}, MH</div><div class="region-caption">${state.farm?.name||'My farm'} · ${esc(state.farm?.district||'Nashik')}</div></div><div class="profile"><div class="avatar">${esc(state.user.name.slice(0,1).toUpperCase())}</div><div><div class="profile-name">${esc(state.user.name)}</div><div class="profile-type">${state.user.farmerType==='beginner'?t('beginner'):t('experienced')}</div></div><button class="logout" id="logout" title="${t('logout')}">↪</button></div></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" id="menu">☰</button><div class="crumb">AgriSathi <span style="padding:0 7px;color:#aeb7ae">/</span><strong>${t(state.page)}</strong></div><div class="top-actions"><span class="pill"><span class="live-dot" style="background:${state.weather?'#65b774':'#d5a25f'}"></span>${state.weather?t('live'):t('uncertain')}</span><button class="lang-btn" id="language">${state.language==='en'?'मराठी':'English'}</button></div></header><div class="content" id="content">${pageContent()}</div></main></div>`;attachGlobal();attachPage();}
function navItem([id,icon,key]){return `<button data-page="${id}" class="${state.page===id?'active':''}"><span class="nav-ico">${icon}</span>${t(key)}</button>`}
function attachGlobal(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.sidebar=false;render();});q('logout').onclick=async()=>{await api('/api/logout',{method:'POST',body:'{}'});state.user=null;state.farms=[];state.chat=[];renderAuth('login');};q('language').onclick=async()=>{state.language=state.language==='en'?'mr':'en';try{const d=await api('/api/profile',{method:'PATCH',body:JSON.stringify({language:state.language})});state.user=d.user;}catch(e){toast(e.message,true)}render();};q('menu').onclick=()=>{state.sidebar=!state.sidebar;document.querySelector('.sidebar').classList.toggle('open',state.sidebar);};}
function pageContent(){const pages={dashboard:dashboardPage,advisory:advisoryPage,planner:plannerPage,disease:diseasePage,soil:soilPage,community:communityPage,history:historyPage,sources:sourcesPage,assistant:geminiPage};const html=(pages[state.page]||dashboardPage)();return state.page==='sources'?html+satelliteStatus():html;}
function satelliteStatus(){return `<div class="grid two page-section"><section class="card"><div class="section-title"><div><h2>Satellite crop monitoring</h2><p>Not connected · no satellite values are fabricated</p></div><span class="confidence limited">ACCESS NEEDED</span></div><p class="rec-desc">Copernicus Sentinel-2 provides open imagery, but the processing APIs require an account and OAuth access token. No plot-level vegetation index is shown until credentials and a valid field boundary are available.</p><a class="source-link" href="https://dataspace.copernicus.eu/analyse/apis" target="_blank" rel="noreferrer"><span><strong>Copernicus Data Space API access</strong><small>Registration and token setup are required for processing requests.</small></span>↗</a></section><section class="card"><div class="section-title"><div><h2>Community database scope</h2><p>Local SQLite · this computer only</p></div><span class="confidence limited">LOCAL</span></div><p class="rec-desc">Real reports submitted here are stored locally. They are not shared with other devices until a managed PostgreSQL project is configured. No sample farmer reports are inserted.</p><a class="source-link" href="https://supabase.com/docs/guides/database/secure-data" target="_blank" rel="noreferrer"><span><strong>PostgreSQL / row-level security migration</strong><small>Cloud sharing requires project credentials and access policies.</small></span>↗</a></section></div>`;}
function head(eyebrow,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p></div>${action}</div>`}
function stat(label,val,detail,icon){return `<article class="card stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${val}</div><div class="stat-detail">${detail}</div></article>`}
function weatherIcon(code){if(code===0)return '☀️';if([1,2].includes(code))return '🌤️';if(code===3)return '☁️';if([45,48].includes(code))return '🌫️';if([51,53,55,61,63,65,80,81,82].includes(code))return '🌧️';if([95,96,99].includes(code))return '⛈️';return '🌦️'}
function weatherPanel(){if(!state.weather)return `<div class="weather-empty">${t('noForecast')}<br><button class="link-btn" id="retry-weather" style="color:#fff;margin-top:10px">↻ Retry</button>${state.weatherError?`<br><small>${esc(state.weatherError)}</small>`:''}</div>`;const w=state.weather,now=w.current,days=w.daily;return `<div class="wx-main"><div class="wx-symbol">${weatherIcon(days[0].code)}</div><div><div class="wx-temp">${Math.round(now.temperature_2m)}°</div><div class="wx-desc">${t('temperature')} ${Math.round(now.apparent_temperature)}° feels like</div></div></div><div class="wx-days">${days.map((d,i)=>`<div class="wx-day"><div class="wx-day-name">${i===0?'Today':fmt(d.date,{weekday:'short'})}</div><div class="wx-day-temp">${weatherIcon(d.code)} &nbsp;${Math.round(d.max)}° / ${Math.round(d.min)}°</div><div class="wx-day-rain">☂ ${d.rainProbability??'—'}% · ${d.rain??'—'} mm</div></div>`).join('')}</div><div class="source-note">${t('forecastAttribution')} · fetched ${fmt(w.fetchedAt,{hour:'2-digit',minute:'2-digit'})}</div>`}
function dashboardPage(){const w=state.weather?.daily?.[0],latest=state.soil[0],crop=state.farm?.crop||'Tomato';return `${head(t('today'),`${t('hello')}, ${esc(state.user.name.split(' ')[0])}`,t('welcome'),`<button class="btn" data-go="advisory">✳ &nbsp;${t('newAdvice')}</button>`)}<div class="grid stats">${stat(t('crop'),crop==='Grape'?t('grape'):t('tomato'),state.farm?.name||'My Nashik farm','🌱')}${stat(t('soilLatest'),latest?`${latest.ph??'—'} pH`:t('unknownSoil'),latest?fmt(latest.tested_at,{day:'numeric',month:'short',year:'numeric'}):t('soilMissing'),'◌')}${stat(t('advisories'),state.advisories.length,state.advisories.length?'Saved to this farm':'Generate from live forecast','✳')}${stat(t('rain'),w?.rain!=null?`${w.rain} mm`:'—',w?`${w.rainProbability??'—'}% ${t('rainChance').toLowerCase()}`:t('uncertain'),'☂')}</div><div class="grid two page-section"><section class="card weather-card"><div class="section-title"><div><h2>${t('weather')}</h2><p>${t('weatherSub')} · ${new Intl.DateTimeFormat(state.language==='mr'?'mr-IN':'en-IN',{dateStyle:'medium'}).format(new Date())}</p></div><button class="link-btn" id="refresh-weather" style="color:#d9e6d9">↻</button></div>${weatherPanel()}</section><section class="card"><div class="section-title"><div><h2>${t('quick')}</h2><p>${t('useful')}</p></div></div><div class="quick-list"><button class="quick-item" data-go="planner"><span class="quick-icon">🌾</span><span class="quick-text"><span class="quick-title">${t('plannerTitle')}</span><span class="quick-sub">${t('provisional')}</span></span><span class="arrow">›</span></button><button class="quick-item" data-go="disease"><span class="quick-icon">🔬</span><span class="quick-text"><span class="quick-title">${t('diseaseTitle')}</span><span class="quick-sub">${t('modelInfo')}: ONNX · PlantVillage</span></span><span class="arrow">›</span></button><button class="quick-item" data-go="soil"><span class="quick-icon">♧</span><span class="quick-text"><span class="quick-title">${t('soilTitle')}</span><span class="quick-sub">${latest?t('latest'):t('soilMissing')}</span></span><span class="arrow">›</span></button></div></section></div><div class="grid two page-section"><section class="card"><div class="section-title"><div><h2>${t('forecast')}</h2><p>${state.weather?`${t('refreshed')} ${fmt(state.weather.fetchedAt,{hour:'2-digit',minute:'2-digit'})}`:t('noForecast')}</p></div><button class="link-btn" data-go="advisory">${t('advisory')} →</button></div>${state.weather?`<div class="forecast-row">${state.weather.daily.map((d,i)=>`<div class="forecast-day"><div class="day">${i===0?'Today':fmt(d.date,{weekday:'short',day:'numeric'})}</div><div class="icon">${weatherIcon(d.code)}</div><div class="temps">${Math.round(d.max)}° / ${Math.round(d.min)}°</div><div class="rain">☂ ${d.rainProbability??'—'}% · ${d.rain??'—'} mm</div></div>`).join('')}</div>`:`<div class="empty">${t('noForecast')} ${state.weatherError?esc(state.weatherError):''}</div>`}</section><section class="card"><div class="section-title"><div><h2>${t('activity')}</h2><p>${t('records')}</p></div><button class="link-btn" data-go="history">${t('open')} →</button></div>${activityPreview()}</section></div><div class="page-section banner info"><strong>${t('sourceLabel')}:</strong> ${t('forecastAttribution')}. ${t('noFabricated')}</div>`}
function activityPreview(){const rows=[...state.soil.map(x=>({name:`Soil card · pH ${x.ph??'—'}`,date:x.created_at,icon:'◌'})),...state.seasons.map(x=>({name:`${x.crop} season${x.variety?' · '+x.variety:''}`,date:x.created_at,icon:'🌱'})),...state.observations.map(x=>({name:x.note,date:x.created_at,icon:'✎'})),...state.advisories.map(x=>({name:x.summary,date:x.created_at,icon:'✳'}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);return rows.length?`<div class="activity-list">${rows.map(x=>`<div class="activity-item"><div class="activity-dot"></div><div><div class="activity-name">${esc(x.name)}</div><div class="activity-date">${fmt(x.date,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</div></div></div>`).join('')}</div>`:`<div class="empty"><div class="empty-icon">⌑</div>${t('noActivity')}</div>`}
function advisoryPage(){return `${head(t('nashik'),t('advisoryTitle'),t('advisoryDesc'),`<button class="btn" id="generate-advisory" ${state.weather?'':'disabled'}>✳ &nbsp;${t('generate')}</button>`)}${!state.weather?`<div class="banner warn">${t('needForecast')} ${state.weatherError?esc(state.weatherError):''}</div>`:`<div class="grid two"><div><div class="card"><div class="section-title"><div><h2>${t('forecast')}</h2><p>Open-Meteo · ${fmt(state.weather.fetchedAt,{dateStyle:'medium',timeStyle:'short'})}</p></div><span class="confidence good">LIVE</span></div><div class="forecast-row">${state.weather.daily.map((d,i)=>`<div class="forecast-day"><div class="day">${i===0?'Today':fmt(d.date,{weekday:'short',day:'numeric'})}</div><div class="icon">${weatherIcon(d.code)}</div><div class="temps">${Math.round(d.max)}° / ${Math.round(d.min)}°</div><div class="rain">☂ ${d.rainProbability??'—'}% · ${d.rain??'—'} mm</div></div>`).join('')}</div><p class="page-sub" style="margin-top:15px">Current: ${state.weather.current.temperature_2m}°C · feels ${state.weather.current.apparent_temperature}°C · RH ${state.weather.current.relative_humidity_2m}% · wind ${state.weather.current.wind_speed_10m} km/h</p></div><div class="card"><div class="section-title"><div><h2>${t('whatIs')}</h2><p>${t('sourceLabel')}: Open-Meteo live model forecast</p></div></div><div class="field"><label>${t('selectCrop')}</label><select id="advisory-crop"><option value="Tomato">${t('tomato')}</option><option value="Grape">${t('grape')}</option></select></div><div class="banner info" style="margin-top:14px">The app generates weather actions only from this live forecast. Crop-stage or soil-specific actions require those records and an official locally relevant bulletin.</div><div id="advisory-result"></div></div></div><div class="page-section"><div class="section-title"><h2>${t('advisories')}</h2></div>${advisoryHistory()}</div>`}<div class="page-section banner">IMD’s documented forecast and Agromet API endpoints currently require authorization (HTTP 401 in our check). The app does not represent Open-Meteo values as IMD data. <a href="https://mausam.imd.gov.in/responsive/agromet_adv_ser_block_current_en.php" target="_blank" rel="noreferrer">Open official IMD Agromet bulletins ↗</a></div>`}
function advisoryHistory(){return state.advisories.length?`<div class="grid">${state.advisories.map(a=>`<article class="card"><div class="section-title"><div><h2>${esc(a.summary)}</h2><p>${fmt(a.created_at,{dateStyle:'medium',timeStyle:'short'})} · ${esc(a.source_name)}</p></div><span class="confidence good">${esc(a.confidence)}</span></div><ul>${a.actions.map(x=>`<li style="margin:7px 0;color:#576358;font-size:12px">${esc(x)}</li>`).join('')}</ul><small>Data source: <a href="${esc(a.source_url)}" target="_blank" rel="noreferrer">${esc(a.source_name)}</a> · fetched ${esc(a.source_issued_at||'')}</small></article>`).join('')}</div>`:`<div class="empty">No advisories saved yet. Generate one from the live forecast above.</div>`}
function soilPage(){return `${head(t('soilData'),t('soilTitle'),t('soilDesc'))}<div class="grid two"><section class="card"><div class="section-title"><div><h2>${t('save')}</h2><p>${t('soilParams')}</p></div></div><form id="soil-form"><div class="form-grid"><div class="field"><label>${t('tested')}</label><input type="date" name="testedAt" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>${t('testSource')}</label><select name="source"><option>Soil Health Card</option><option>Laboratory report</option><option>Other certified soil test</option></select></div>${[['ph','pH','0','14'],['ec','ec','0','','step="any"'],['organic_carbon','oc','0','','step="any"'],['nitrogen','nitrogen','0','','step="any"'],['phosphorus','phosphorus','0','','step="any"'],['potassium','potassium','0','','step="any"']].map(([n,k,min,max,step=''])=>`<div class="field"><label>${t(k)}</label><input type="number" name="${n}" min="${min}" ${max?`max="${max}"`:''} ${step} step="any" placeholder="${t('unknownSoil')}"></div>`).join('')}</div><div class="form-actions"><button class="btn" type="submit">${t('save')}</button></div></form></section><section><div class="banner info">${t('soilDesc')} <br><br><a href="https://soilhealth.dac.gov.in/files/FAQ_Final_English.pdf" target="_blank" rel="noreferrer">Official Soil Health Card guide ↗</a> · <a href="https://soilhealth.dac.gov.in/" target="_blank" rel="noreferrer">Portal ↗</a></div><div class="card page-section"><div class="section-title"><h2>${t('savedTests')}</h2><span class="confidence">${state.soil.length}</span></div>${state.soil.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('tested')}</th><th>pH</th><th>EC</th><th>OC</th><th>N · P · K</th><th>${t('testSource')}</th></tr></thead><tbody>${state.soil.map(s=>`<tr><td>${fmt(s.tested_at,{day:'numeric',month:'short',year:'numeric'})}</td><td>${s.ph??'—'}</td><td>${s.ec??'—'}</td><td>${s.organic_carbon??'—'}</td><td>${s.nitrogen??'—'} · ${s.phosphorus??'—'} · ${s.potassium??'—'}</td><td>${esc(s.source)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">◌</div>${t('noSoil')}</div>`}</div></section></div>`}
function plannerPage(){const latest=state.soil[0];return `${head(t('provisional'),t('plannerTitle'),t('plannerDesc'))}<div class="grid two"><section class="card"><div class="section-title"><div><h2>Tell us about this plot</h2><p>Unknown values are allowed; they reduce the evidence available.</p></div></div><form id="planner-form"><div class="form-grid"><div class="field"><label>${t('selectCrop')} preference</label><select name="crop"><option value="Tomato">Tomato / टोमॅटो</option><option value="Grape">Grape / द्राक्ष</option><option value="both">Compare both</option></select></div><div class="field"><label>${t('water')}</label><select name="water"><option value="reliable">Reliable irrigation</option><option value="limited">Limited water</option><option value="rainfed">Rainfed</option><option value="unknown">Not sure</option></select></div><div class="field"><label>${t('area')}</label><input type="number" name="area" min="0.01" step="0.01" value="${state.farm?.area||''}" placeholder="e.g. 0.5"></div><div class="field"><label>${t('soilInput')}</label><select name="soil"><option value="latest">Use latest saved soil test ${latest?`(pH ${latest.ph??'—'})`:'(none saved)'}</option><option value="unknown">I do not have a test</option></select></div><div class="field full"><label>${t('goal')}</label><select name="goal"><option value="low-input">Lower input and simpler care</option><option value="water">Use less water</option><option value="market">Potential local market value</option><option value="learning">Learning / hobby scale</option></select></div></div><div class="form-actions"><button class="btn" type="submit">${t('plan')} →</button></div></form></section><section class="card"><div class="section-title"><div><h2>How the shortlist works</h2><p>Evidence and assumptions are shown for each crop.</p></div><span class="confidence limited">${t('provisional')}</span></div><div class="source-list"><a class="source-link" href="https://icar.gov.in/sites/default/files/Circulars/ICAR%20En-Kharif%20Agro-Advisories%20for%20Farmers%202025.pdf" target="_blank" rel="noreferrer"><span><strong>ICAR · Kharif agro-advisory 2025</strong><small>Includes Northern Maharashtra region and grape guidance</small></span>↗</a><a class="source-link" href="https://icar.org.in/en/icar-nrc-grapes-pune-partners-maharashtra-state-grape-growers-association-empower-future-farmers" target="_blank" rel="noreferrer"><span><strong>ICAR-NRCG · Nashik grape growers</strong><small>Regional capacity-building and crop guidance</small></span>↗</a></div><div class="banner info" style="margin-top:15px">The planner does not invent a seed variety or use unsourced yield claims. Use an official bulletin and your soil card before purchasing seed.</div></section></div><div id="planner-results" class="grid two page-section"></div>`}
function diseasePage(){return `${head(t('modelInfo'),t('diseaseTitle'),t('diseaseDesc'))}<div class="grid two disease-layout"><section class="card"><div class="section-title"><div><h2>${t('choosePhoto')}</h2><p>JPEG, PNG, or WEBP · up to 10 MB · local screen by default</p></div></div><label class="drop-zone" id="drop-zone"><div style="font-size:27px">▧</div><strong>${t('upload')}</strong><p>Drop an image here or click to browse.</p><input type="file" id="leaf-image" accept="image/jpeg,image/png,image/webp"></label><img id="image-preview" class="preview-img" hidden alt="Selected leaf photo"><div class="form-grid page-section"><div class="field"><label>${t('cropQuestion')}</label><select id="disease-crop"><option value="Tomato">${t('tomato')}</option><option value="Grape">${t('grape')}</option></select></div></div><label class="check-row" style="display:flex;gap:10px;align-items:flex-start;margin:14px 0;font-size:13px;line-height:1.5"><input type="checkbox" id="gemini-image-consent" style="margin-top:3px"><span>${t('sharePhotoConsent')}</span></label><div class="form-actions"><button class="btn" id="analyze" disabled>${t('classify')}</button></div><div id="disease-result"></div></section><section><div class="card"><div class="section-title"><div><h2>Model card</h2><p>Published ONNX model + optional Gemini vision screen</p></div><span class="confidence good">ONNX + Gemini</span></div><p style="font-size:12px;line-height:1.7;color:#59655b">ConCaPlant / MobileNetV3 runs locally. If you opt in, Gemini compares the photo with the model's published PlantVillage labels. Its result is constrained to those labels or “unknown”.</p><div class="banner warn"><strong>Field use:</strong> Training data are curated leaf images, not independently verified Nashik field images. Lighting, background, mixed symptoms, and unsupported conditions can lead to errors. Treat output as screening only. Neither model confirms a diagnosis.</div><p style="font-size:11px;color:var(--muted);margin-top:15px"><a target="_blank" rel="noreferrer" href="https://huggingface.co/imaflower/plantvillage-mobilenetv3">Model card and license ↗</a><br><a target="_blank" rel="noreferrer" href="https://github.com/spMohanty/PlantVillage-Dataset">PlantVillage dataset ↗</a></p></div><div class="card page-section"><div class="section-title"><h2>Model runs</h2><span class="confidence">${state.observations.filter(o=>o.stage==='disease-check').length}</span></div><div class="empty">Each completed analysis is saved with its model label and confidence. Nothing has been analyzed on this farm yet.</div></div></section></div>`}
function communityPage(){const reports=state.community.reports||[],summary=state.community.summary||[];return `${head(t('communityTitle'),t('communityTitle'),t('communityDesc'),`<span class="pill">${reports.length} ${t('reports')}</span>`)}<div class="grid two"><section class="card"><div class="section-title"><div><h2>${t('share')}</h2><p>Your report helps build a local evidence pool.</p></div></div><form id="community-form"><div class="form-grid"><div class="field"><label>${t('selectCrop')}</label><select name="crop"><option>Tomato</option><option>Grape</option></select></div><div class="field"><label>${t('variety')}</label><input name="variety" required maxlength="80" placeholder="Name exactly as on seed packet"></div><div class="field"><label>${t('season')}</label><select name="season"><option>Kharif</option><option>Rabi</option><option>Summer</option><option>Perennial</option></select></div><div class="field"><label>Sowing month</label><select name="sowingMonth"><option value="">Unknown</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}">${new Intl.DateTimeFormat(state.language==='mr'?'mr-IN':'en-IN',{month:'long'}).format(new Date(2026,i,1))}</option>`).join('')}</select></div><div class="field"><label>${t('outcome')}</label><select name="outcome"><option value="good">${t('good')}</option><option value="average">${t('average')}</option><option value="poor">${t('poor')}</option></select></div><div class="field"><label>${t('water')}</label><select name="conditions"><option>Reliable irrigation</option><option>Limited irrigation</option><option>Rainfed</option><option>Unknown</option></select></div></div><div class="form-actions"><button class="btn" type="submit">${t('report')}</button></div></form></section><section class="card"><div class="section-title"><div><h2>${t('reports')} by variety</h2><p>Only real, user-submitted reports are counted.</p></div></div>${summary.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('crop')}</th><th>${t('variety')}</th><th>${t('season')}</th><th>${t('reports')}</th><th>Good</th></tr></thead><tbody>${summary.map(s=>`<tr><td>${esc(s.crop)}</td><td>${esc(s.variety)}</td><td>${esc(s.season)}</td><td>${s.reports}</td><td>${s.good}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">◎</div>${t('noReports')}<br><br>${t('noFabricated')}</div>`}</section></div><div class="card page-section"><div class="section-title"><div><h2>Privacy and quality</h2><p>Reports are opt-in and shown without farmer names or precise plot locations.</p></div></div><div class="banner info">A crowd result becomes useful only when there are enough reports from comparable seasons and farm conditions. The app shows report counts so a single report is never presented as a consensus.</div></div>`}
function historyPage(){return `${head(t('workspace'),t('historyTitle'),t('historyDesc'),`<button class="btn" id="add-season">＋ ${t('seasonRecord')}</button>`)}<div class="grid two"><section class="card"><div class="section-title"><div><h2>${t('cropHistory')}</h2><p>Crop seasons saved on this device</p></div><span class="confidence">${state.seasons.length}</span></div>${state.seasons.length?`<div class="table-wrap"><table class="table"><thead><tr><th>${t('crop')}</th><th>${t('variety')}</th><th>${t('season')}</th><th>${t('sowing')}</th><th>${t('harvest')}</th><th>${t('outcome')}</th></tr></thead><tbody>${state.seasons.map(s=>`<tr><td>${esc(s.crop)}</td><td>${esc(s.variety||'—')}</td><td>${esc(s.season||'—')}</td><td>${esc(s.sowing_date||'—')}</td><td>${esc(s.harvest_date||'—')}</td><td>${esc(s.outcome||'—')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No crop seasons saved yet.</div>`}</section><section class="card"><div class="section-title"><div><h2>${t('observation')}</h2><p>Note a crop stage, local rain, or field condition</p></div></div><form id="observation-form"><div class="form-grid"><div class="field"><label>${t('observedAt')||'Date'}</label><input type="date" name="observedAt" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>${t('stage')}</label><select name="stage"><option>Before sowing</option><option>Vegetative</option><option>Flowering</option><option>Fruiting</option><option>Harvest</option><option>Weather observation</option></select></div><div class="field full"><label>${t('note')}</label><textarea name="note" required maxlength="1200" placeholder="What did you see in the field today?"></textarea></div></div><div class="form-actions"><button class="btn" type="submit">${t('add')}</button></div></form></section></div><section class="card page-section"><div class="section-title"><div><h2>${t('activity')}</h2><p>Chronological notes, tests, and saved advice</p></div></div>${activityPreview()}</section>`}
function sourcesPage(){return `${head(t('official'),t('sourcesTitle'),t('sourcesDesc'))}<div class="grid two"><section class="card"><div class="section-title"><div><h2>${t('forecastSource')}</h2><p>${state.weather?t('dataAvailable'):t('dataUnavailable')}</p></div><span class="confidence ${state.weather?'good':'limited'}">${state.weather?'CONNECTED':'NO LIVE DATA'}</span></div><div class="source-list"><a class="source-link" href="https://open-meteo.com/en/docs" target="_blank" rel="noreferrer"><span><strong>Open-Meteo Forecast API</strong><small>${state.weather?`Fetched ${fmt(state.weather.fetchedAt,{dateStyle:'medium',timeStyle:'short'})} · Nashik coordinates`:t('noForecast')}</small></span>↗</a><a class="source-link" href="https://open-meteo.com/en/pricing" target="_blank" rel="noreferrer"><span><strong>Usage and license terms</strong><small>Free API is limited to non-commercial use and has no uptime guarantee.</small></span>↗</a><a class="source-link" href="https://api.imd.gov.in/public/api_reference.html" target="_blank" rel="noreferrer"><span><strong>IMD public API reference</strong><small>Documented endpoints currently return 401 without access credentials.</small></span>↗</a><a class="source-link" href="https://mausam.imd.gov.in/responsive/agromet_adv_ser_block_current_en.php" target="_blank" rel="noreferrer"><span><strong>IMD Agromet district bulletins</strong><small>Official advisories page · content is not copied into this app.</small></span>↗</a></div></section><section class="card"><div class="section-title"><div><h2>${t('modelInfo')}</h2><p>Real ONNX model, loaded on analysis</p></div><span class="confidence good">MIT</span></div><div class="source-list"><a class="source-link" href="https://huggingface.co/imaflower/plantvillage-mobilenetv3" target="_blank" rel="noreferrer"><span><strong>ConCaPlant MobileNetV3</strong><small>PlantVillage labels · available model card and weights</small></span>↗</a><a class="source-link" href="https://github.com/spMohanty/PlantVillage-Dataset" target="_blank" rel="noreferrer"><span><strong>PlantVillage dataset</strong><small>CC BY-SA 3.0 dataset; controlled imagery</small></span>↗</a><a class="source-link" href="https://soilhealth.dac.gov.in/" target="_blank" rel="noreferrer"><span><strong>Soil Health Card portal</strong><small>Soil values must come from a card or lab report.</small></span>↗</a><a class="source-link" href="https://icar.gov.in/sites/default/files/Circulars/ICAR%20En-Kharif%20Agro-Advisories%20for%20Farmers%202025.pdf" target="_blank" rel="noreferrer"><span><strong>ICAR Kharif Agromet advisories 2025</strong><small>Regional guidance reference for Maharashtra/Northern Maharashtra</small></span>↗</a></div></section></div><div class="page-section banner warn"><strong>Data honesty:</strong> ${t('noFabricated')} Real recommendations need season, location, soil, water access, and an up-to-date official source. Disease predictions are model output, not expert-confirmed diagnoses.</div>`}

function geminiPage(){return `${head(t('assistant'),t('chatTitle'),t('chatDesc'))}<section class="card chat-card"><div class="banner info">Gemini uses your saved farm location, crop, and latest soil test as context. It does not replace local expert advice.</div><div id="chat-messages" class="chat-messages" role="log" aria-live="polite"></div><form id="gemini-chat-form" class="chat-form"><label class="sr-only" for="gemini-chat-input">${t('chatPlaceholder')}</label><textarea id="gemini-chat-input" maxlength="1800" required placeholder="${t('chatPlaceholder')}"></textarea><div class="chat-actions"><span class="chat-voice-note">${t('chatVoiceNote')}</span><div><button class="btn secondary" id="gemini-mic" type="button">🎙 ${t('chatMic')}</button> <button class="btn" id="gemini-send" type="submit">${t('chatSend')} →</button></div></div></form></section>`}
let chatVoiceReply=false,chatRecorder=null,chatStream=null,chatChunks=[],chatRecordTimer=null,activeSpeechAudio=null,activeSpeechAbort=null,activeSpeechButton=null,activeSpeechUrl=null;
function paintChat(){const box=q('chat-messages');if(!box)return;const items=state.chat.length?state.chat:[{role:'model',text:t('chatWelcome')}];box.innerHTML=items.map((m,i)=>`<article class="chat-message ${m.role==='user'?'user':'assistant'}"><div class="chat-message-role">${m.role==='user'?(state.language==='mr'?'तुम्ही':'You'):'AgriSathi · Gemini'}</div><div class="chat-message-text">${esc(m.text)}</div>${m.role==='model'&&state.chat.length?`<button type="button" class="text-button" id="chat-speak-${i}" data-chat-speak="${i}">🔊 ${t('chatListen')}</button>`:''}</article>`).join('');box.scrollTop=box.scrollHeight}
async function sendGeminiMessage(){const input=q('gemini-chat-input'),form=q('gemini-chat-form');if(!input||!form)return;const text=input.value.trim();if(!text)return;const send=q('gemini-send'),mic=q('gemini-mic');if(send.disabled)return;const voiceReply=chatVoiceReply;chatVoiceReply=false;state.chat.push({role:'user',text});input.value='';paintChat();send.disabled=true;mic.disabled=true;send.textContent='…';try{const d=await api('/api/gemini/chat',{method:'POST',body:JSON.stringify({messages:state.chat.slice(-16)})});state.chat.push({role:'model',text:d.text});paintChat();if(voiceReply)await speakChat(d.text,q(`chat-speak-${state.chat.length-1}`))}catch(err){state.chat.pop();input.value=text;paintChat();toast(err.message,true)}finally{send.disabled=false;mic.disabled=false;mic.innerHTML='🎙 '+t('chatMic');send.textContent=t('chatSend')+' →';input.focus()}}
function attachChat(){if(!q('gemini-chat-form'))return;paintChat();const form=q('gemini-chat-form'),send=q('gemini-send'),input=q('gemini-chat-input');form.addEventListener('submit',e=>{e.preventDefault();sendGeminiMessage()});send.addEventListener('click',e=>{e.preventDefault();sendGeminiMessage()});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendGeminiMessage()}});q('gemini-mic').onclick=()=>{if(chatRecorder?.state==='recording'){chatRecorder.stop();clearTimeout(chatRecordTimer);return}startGeminiRecording()};q('chat-messages').onclick=e=>{const b=e.target.closest('[data-chat-speak]');if(b){const msg=state.chat[Number(b.dataset.chatSpeak)];if(msg?.role==='model'){if(b.dataset.speechState)stopGeminiSpeech();else speakChat(msg.text,b)}}}}
async function startGeminiRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast(t('chatMicUnsupported'),true);return}const button=q('gemini-mic');button.disabled=true;try{chatStream=await navigator.mediaDevices.getUserMedia({audio:true});const formats=['audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus','audio/mp4'],mimeType=formats.find(x=>MediaRecorder.isTypeSupported(x));chatChunks=[];chatRecorder=new MediaRecorder(chatStream,mimeType?{mimeType}:undefined);chatRecorder.ondataavailable=e=>{if(e.data.size)chatChunks.push(e.data)};chatRecorder.onerror=()=>{chatStream?.getTracks().forEach(track=>track.stop());chatStream=null;button.disabled=false;button.innerHTML='🎙 '+t('chatMic');toast(state.language==='mr'?'रेकॉर्डिंग अयशस्वी. पुन्हा प्रयत्न करा.':'Recording failed. Please try again.',true)};chatRecorder.onstop=async()=>{clearTimeout(chatRecordTimer);chatStream?.getTracks().forEach(track=>track.stop());chatStream=null;const blob=new Blob(chatChunks,{type:chatRecorder.mimeType||'audio/webm'});chatRecorder=null;chatChunks=[];if(!blob.size){button.disabled=false;button.innerHTML='🎙 '+t('chatMic');toast(state.language==='mr'?'आवाज रेकॉर्ड झाला नाही. पुन्हा प्रयत्न करा.':'No audio was recorded. Please try again.',true);return}if(blob.size>3_000_000){button.disabled=false;button.innerHTML='🎙 '+t('chatMic');toast(state.language==='mr'?'रेकॉर्डिंग १५ सेकंदांपेक्षा कमी ठेवा.':'Keep the recording under 15 seconds.',true);return}button.disabled=true;button.textContent=t('chatTranscribing');try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the recording.'));reader.readAsDataURL(blob)});const d=await api('/api/gemini/transcribe',{method:'POST',body:JSON.stringify({mimeType:blob.type,audioBase64:String(dataUrl).split(',')[1]})});q('gemini-chat-input').value=d.text;chatVoiceReply=true;sendGeminiMessage()}catch(err){toast(err.message,true);button.disabled=false;button.innerHTML='🎙 '+t('chatMic')}};chatRecorder.start();button.disabled=false;button.textContent='■ '+t('chatStop');chatRecordTimer=setTimeout(()=>{if(chatRecorder?.state==='recording')chatRecorder.stop()},15000)}catch(err){chatStream?.getTracks().forEach(track=>track.stop());chatStream=null;button.disabled=false;button.innerHTML='🎙 '+t('chatMic');toast(err.name==='NotAllowedError'?t('chatMicDenied'):err.message||t('chatMicUnsupported'),true)}}
function resetSpeechButton(button){if(button){button.dataset.speechState='';button.disabled=false;button.innerHTML=`🔊 ${t('chatListen')}`}}
function stopGeminiSpeech(){if(activeSpeechAbort)activeSpeechAbort.abort();if(activeSpeechAudio){activeSpeechAudio.pause();activeSpeechAudio.currentTime=0}if(activeSpeechUrl){URL.revokeObjectURL(activeSpeechUrl);activeSpeechUrl=null}resetSpeechButton(activeSpeechButton);activeSpeechAudio=null;activeSpeechAbort=null;activeSpeechButton=null}
async function speakChat(text,button){if(activeSpeechAudio||activeSpeechAbort)stopGeminiSpeech();const controller=new AbortController();activeSpeechAbort=controller;activeSpeechButton=button;if(button){button.dataset.speechState='loading';button.disabled=false;button.textContent=state.language==='mr'?'तयार करत आहे · थांबवा':'Preparing audio · Stop'}try{const speechText=text.slice(0,900);const d=await api('/api/gemini/speech',{method:'POST',body:JSON.stringify({text:speechText,language:state.language}),signal:controller.signal});if(controller.signal.aborted)return;const bytes=Uint8Array.from(atob(d.audioBase64),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:d.mimeType||'audio/wav'})),audio=new Audio(url);activeSpeechAudio=audio;activeSpeechUrl=url;if(button){button.dataset.speechState='playing';button.textContent=state.language==='mr'?'थांबवा':'Stop'}audio.onended=()=>stopGeminiSpeech();audio.onerror=()=>{stopGeminiSpeech();toast(state.language==='mr'?'ऑडिओ प्ले करता आला नाही.':'Could not play the generated audio.',true)};await audio.play()}catch(err){if(err.name!=='AbortError'){stopGeminiSpeech();toast(err.message,true)}}finally{if(!activeSpeechAudio&&!activeSpeechAbort)resetSpeechButton(button);if(activeSpeechAbort===controller){activeSpeechAbort=null;if(!activeSpeechAudio)resetSpeechButton(button)}}}
function attachPage(){const go=b=>{state.page=b.dataset.go;render()};document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b));q('refresh-weather')?.addEventListener('click',async()=>{await loadWeather();render();if(!state.weather)toast(state.weatherError,true)});q('retry-weather')?.addEventListener('click',async()=>{await loadWeather();render();if(!state.weather)toast(state.weatherError,true)});q('generate-advisory')?.addEventListener('click',generateAdvisory);q('soil-form')?.addEventListener('submit',saveSoil);q('planner-form')?.addEventListener('submit',runPlanner);q('community-form')?.addEventListener('submit',saveCommunity);q('observation-form')?.addEventListener('submit',saveObservation);q('add-season')?.addEventListener('click',seasonModal);q('content')?.addEventListener('click',async e=>{const b=e.target.closest('[data-speak]');if(!b)return;const text=b.dataset.speak;b.disabled=true;b.textContent=t('generatingAudio');try{const d=await api('/api/gemini/speech',{method:'POST',body:JSON.stringify({text,language:state.language})});const bytes=Uint8Array.from(atob(d.audioBase64),c=>c.charCodeAt(0));let player=q('advisory-audio');if(!player){player=document.createElement('audio');player.id='advisory-audio';player.controls=true;player.style.display='block';player.style.marginTop='10px';b.after(player)}if(player.dataset.url)URL.revokeObjectURL(player.dataset.url);const url=URL.createObjectURL(new Blob([bytes],{type:d.mimeType||'audio/wav'}));player.src=url;player.dataset.url=url;await player.play();b.textContent='Read aloud again'}catch(err){b.textContent='Read aloud';toast(err.message,true)}finally{b.disabled=false}});attachDisease();attachChat();}
async function generateAdvisory(){const button=q('generate-advisory');button.disabled=true;button.textContent=t('loading');try{const d=await api(`/api/advisories?farmId=${encodeURIComponent(state.farm.id)}`,{method:'POST',body:JSON.stringify({weather:state.weather,crop:q('advisory-crop')?.value||state.farm.crop})});await loadRecords();render();const result=q('advisory-result');if(result)result.innerHTML=renderAdvice(d.advisory);toast(t('activitySaved'));}catch(e){toast(e.message,true);button.disabled=false;button.textContent=t('generate');}}
function renderAdvice(a){const spoken=[a.summary,...a.actions].join('. ');return `<article class="result"><div class="section-title"><div><h2>${esc(a.summary)}</h2><p>${t('valid')}: ${esc(a.valid_until||'—')} · ${esc(a.source_name)}</p></div><span class="confidence ${a.confidence==='forecast-only'?'limited':'good'}">${esc(a.confidence)}</span></div><ul>${a.actions.map(x=>`<li style="margin:8px 0;line-height:1.55;color:#59655b">${esc(x)}</li>`).join('')}</ul><button class="btn secondary" data-speak="${esc(spoken)}">${t('readGemini')}</button><div class="banner info">${esc(a.scope||'Weather-based advice only.')} <a href="${esc(a.source_url)}" target="_blank" rel="noreferrer">Source ↗</a></div></article>`}async function saveSoil(e){e.preventDefault();const f=new FormData(e.currentTarget),payload=Object.fromEntries(f);try{await api(`/api/soil?farmId=${encodeURIComponent(state.farm.id)}`,{method:'POST',body:JSON.stringify(payload)});await loadRecords();render();toast(t('activitySaved'));}catch(err){toast(err.message,true)}}
function runPlanner(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));const latest=f.soil==='latest'?state.soil[0]:null;const crops=f.crop==='both'?['Tomato','Grape']:[f.crop];const div=q('planner-results');const rainDays=state.weather?.daily?.filter(d=>Number.isFinite(Number(d.rain)))||[];const rain=rainDays.reduce((n,d)=>n+Number(d.rain||0),0);const farmerType=state.user?.farmerType==='beginner';const preference=f.goal==='learning'?'You selected learning / hobby scale. Compare setup cost and the time you can give each week before committing.':f.goal==='water'?'You prioritized water use. The 5-day rain total is context only; it cannot establish seasonal water sufficiency.':f.goal==='market'?'You prioritized market potential, but live mandi prices and buyer demand are not connected, so this app cannot rank expected returns.':'You prioritized lower inputs. No validated local input-cost comparison is available yet.';const water=f.water==='reliable'?'You reported reliable irrigation.':f.water==='limited'?'You reported limited water; ask the local KVK to check crop-specific water feasibility.':f.water==='rainfed'?'You reported rainfed conditions; this short forecast cannot establish crop suitability.':'Water access is unknown.';const soil=latest?`Saved test (${esc(latest.source)} · ${esc(latest.tested_at)}): pH ${latest.ph??'not reported'}, EC ${latest.ec??'not reported'}, organic carbon ${latest.organic_carbon??'not reported'}%. Values are shown for review; no unsupported suitability score is calculated.`:'No soil test selected. Ask a Soil Testing Laboratory for a current Soil Health Card before making a soil-dependent decision.';const area=Number(f.area)>0?`${Number(f.area).toLocaleString()} acres (${(Number(f.area)*4046.8564224).toFixed(0)} m²)`:'Farm area not provided.';const options={Tomato:{title:t('tomato'),subtitle:'Seasonal crop · check local sowing window, seed source, drainage, and buyer access.',regional:'The linked ICAR advisory discusses tomato practices, including protected cultivation. It does not validate this plot or a particular variety.',effort:'Plan for nursery/transplant timing, regular crop monitoring, and a confirmed market route; local extension guidance should set the actual schedule.'},Grape:{title:t('grape'),subtitle:'Perennial vineyard · treat as a long-term investment requiring site-specific assessment.',regional:'ICAR-NRCG is a crop-specific research source serving the Nashik grape-growing region; consult it or KVK before establishing or renovating a vineyard.',effort:'Check vineyard establishment cost, water quality, trellis/infrastructure, labour, and export or domestic market requirements with an expert before planting.'}};div.innerHTML=`<section class="card page-section"><div class="section-title"><div><div class="eyebrow">COMPARISON · ${rainDays.length?'LIVE WEATHER CONTEXT':'WEATHER UNAVAILABLE'}</div><h2>What your answers tell us</h2></div><span class="confidence limited">NO UNSOURCED RANKING</span></div><p class="rec-desc">${esc(preference)} ${esc(water)}</p><p class="rec-desc"><strong>Plot:</strong> ${esc(area)} · <strong>Soil:</strong> ${soil}</p><p class="rec-desc"><strong>Forecast context:</strong> ${rainDays.length?`${rain.toFixed(1)} mm over ${rainDays.length} forecast days from Open-Meteo. This is not a seasonal rainfall estimate.`:'No live forecast available. Comparison still works without it.'}</p>${farmerType?'<div class="banner info">Because you selected new to farming, we show setup questions and local support links instead of a confidence score.</div>':''}</section>${crops.map(crop=>{const p=options[crop];return `<article class="card rec-card"><div class="rec-rank">${crop===state.farm?.crop?'YOUR CURRENT FARM CROP':'CROP COMPARISON'}</div><div class="rec-title">${p.title}</div><p class="rec-desc">${p.subtitle}</p><div class="page-section"><strong style="font-size:11px">Regional evidence</strong><p class="rec-desc">${p.regional}</p><strong style="font-size:11px">Before you decide</strong><p class="rec-desc">${p.effort}</p><strong style="font-size:11px">Evidence gaps</strong><p class="rec-desc">This app has no live seed stock, current mandi prices, long-range climate outlook, plot boundary / satellite data, or KVK officer review. A five-day forecast and soil card alone cannot establish crop suitability.</p></div><a class="link-btn" target="_blank" rel="noreferrer" href="${crop==='Grape'?'https://icar.org.in/en/icar-nrc-grapes-pune-partners-maharashtra-state-grape-growers-association-empower-future-farmers':'https://icar.gov.in/sites/default/files/Circulars/ICAR-En-Kharif-Agro-Advisories-for-Farmers-2025.pdf'}">Open official crop source ↗</a></article>`}).join('')}`;}
async function saveCommunity(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/community',{method:'POST',body:JSON.stringify(payload)});await loadRecords();render();toast(t('activitySaved'));}catch(err){toast(err.message,true)}}
async function saveObservation(e){e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget));try{await api(`/api/observations?farmId=${encodeURIComponent(state.farm.id)}`,{method:'POST',body:JSON.stringify(payload)});await loadRecords();render();toast(t('activitySaved'));}catch(err){toast(err.message,true)}}
function seasonModal(){const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<section class="modal"><div class="section-title"><h2>${t('seasonRecord')}</h2><button class="logout" data-close>×</button></div><form id="season-form"><div class="form-grid"><div class="field"><label>${t('selectCrop')}</label><select name="crop"><option>Tomato</option><option>Grape</option></select></div><div class="field"><label>${t('variety')}</label><input name="variety" maxlength="80"></div><div class="field"><label>${t('season')}</label><select name="season"><option>Kharif</option><option>Rabi</option><option>Summer</option><option>Perennial</option></select></div><div class="field"><label>${t('outcome')}</label><input name="outcome" placeholder="e.g. still growing"></div><div class="field"><label>${t('sowing')}</label><input name="sowingDate" type="date"></div><div class="field"><label>${t('harvest')}</label><input name="harvestDate" type="date"></div><div class="field full"><label>${t('note')}</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button class="btn">${t('save')}</button><button class="btn secondary" type="button" data-close>${t('cancel')}</button></div></form></section>`;document.body.appendChild(m);m.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>m.remove());m.onclick=e=>{if(e.target===m)m.remove()};$('#season-form',m).onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.currentTarget));try{await api(`/api/crops?farmId=${encodeURIComponent(state.farm.id)}`,{method:'POST',body:JSON.stringify(p)});await loadRecords();m.remove();render();toast(t('activitySaved'));}catch(err){toast(err.message,true)}};}
function attachDisease(){const input=q('leaf-image'),drop=q('drop-zone'),button=q('analyze');if(!input)return;input.onchange=()=>selectImage(input.files?.[0]);drop.onclick=e=>{if(e.target!==input)input.click()};drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');selectImage(e.dataTransfer.files?.[0])};button.onclick=analyzeImage;}
let selectedImage=null;
function selectImage(file){if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>10*1024*1024){toast('Choose a JPEG, PNG, or WEBP image under 10 MB.',true);return}selectedImage=file;const im=q('image-preview');im.src=URL.createObjectURL(file);im.hidden=false;q('analyze').disabled=false;q('disease-result').innerHTML='';}
async function analyzeImage(){
 if(!selectedImage)return;
 const btn=q('analyze'),out=q('disease-result'),useGemini=q('gemini-image-consent')?.checked;
 btn.disabled=true;btn.textContent=t('analyzing');
 out.innerHTML=`<div class="banner info" style="margin-top:12px">Running the published ONNX classifier locally${useGemini?' and preparing your opt-in Gemini visual screen':''}…</div>`;
 try{
  const ortModule=await import('https://cdn.jsdelivr.net/npm/onnxruntime-web@1.23.0/dist/ort.min.mjs');const ort=ortModule.default||ortModule;ort.env.wasm.wasmPaths='https://cdn.jsdelivr.net/npm/onnxruntime-web@1.23.0/dist/';
  const base='https://huggingface.co/imaflower/plantvillage-mobilenetv3/resolve/main/';const [modelResp,labelsResp]=await Promise.all([fetch(base+'model.onnx?download=true'),fetch(base+'class_names.json?download=true')]);if(!modelResp.ok||!labelsResp.ok)throw Error(`Model download failed (${modelResp.status}/${labelsResp.status}). Check internet access and retry.`);
  const labelsRaw=await labelsResp.json(),labels=Array.isArray(labelsRaw)?labelsRaw:(labelsRaw.class_names||labelsRaw.labels||labelsRaw.classes);if(!Array.isArray(labels))throw Error('Published model label map has an unrecognized format.');
  const session=await ort.InferenceSession.create(await modelResp.arrayBuffer(),{executionProviders:['wasm']});const bitmap=await createImageBitmap(selectedImage);const side=256,scale=Math.max(side/bitmap.width,side/bitmap.height),sw=side/scale,sh=side/scale,sx=(bitmap.width-sw)/2,sy=(bitmap.height-sh)/2,canvas=document.createElement('canvas');canvas.width=side;canvas.height=side;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,sx,sy,sw,sh,0,0,side,side);bitmap.close();
  const pixels=ctx.getImageData(0,0,side,side).data,data=new Float32Array(3*side*side),mean=[.485,.456,.406],std=[.229,.224,.225];for(let i=0;i<side*side;i++){data[i]=(pixels[i*4]/255-mean[0])/std[0];data[side*side+i]=(pixels[i*4+1]/255-mean[1])/std[1];data[side*side*2+i]=(pixels[i*4+2]/255-mean[2])/std[2];}
  const tensor=new ort.Tensor('float32',data,[1,3,side,side]),result=await session.run({[session.inputNames[0]]:tensor}),probs=softmax(Array.from(result[session.outputNames[0]].data)),order=probs.map((p,i)=>[p,i]).sort((a,b)=>b[0]-a[0]);
  const crop=q('disease-crop').value,cropToken=crop.toLowerCase(),top=order.slice(0,5).map(([p,i])=>({p,label:String(labels[i]||`class ${i}`)})),matching=top.filter(x=>x.label.toLowerCase().includes(cropToken)),chosen=matching[0]||top[0],belongs=chosen.label.toLowerCase().includes(cropToken),confidence=Math.round(chosen.p*100),parsed=chosen.label.replaceAll('___',' — ').replaceAll('_',' '),low=!belongs||confidence<55;
  out.innerHTML=`<article class="result" id="local-disease-result"><div class="section-title"><div><div class="eyebrow">${low?'UNCERTAIN · SCREENING RESULT':'ON-DEVICE MODEL PREDICTION'}</div><div class="result-label" style="margin-top:6px">${low?'Could not confidently identify a '+esc(crop)+' condition':esc(parsed)}</div></div><span class="confidence ${low?'limited':'good'}">${belongs?confidence+'%':'crop mismatch'}</span></div>${belongs?`<div class="progress"><span style="width:${confidence}%"></span></div>`:''}<p class="rec-desc">This is an unverified screening result, not an expert diagnosis. Check with a local agricultural expert before acting.</p><div class="banner warn" style="margin-top:12px">No pesticide or dosage recommendation is generated from this image.</div></article>`;
  await api(`/api/observations?farmId=${encodeURIComponent(state.farm.id)}`,{method:'POST',body:JSON.stringify({observedAt:new Date().toISOString(),stage:'disease-check',note:`PlantVillage MobileNetV3 · ${crop} · ${chosen.label} · ${confidence}% confidence. Screening only; ${low?'uncertain':'not expert confirmed'}.`})});await loadRecords();
  if(useGemini){
   const bitmap2=await createImageBitmap(selectedImage),maxSide=1024,ratio=Math.min(1,maxSide/Math.max(bitmap2.width,bitmap2.height)),w=Math.round(bitmap2.width*ratio),h=Math.round(bitmap2.height*ratio),cv=document.createElement('canvas');cv.width=w;cv.height=h;cv.getContext('2d').drawImage(bitmap2,0,0,w,h);bitmap2.close();const dataUrl=cv.toDataURL('image/jpeg',.82),imageData=dataUrl.split(',')[1],cropLabels=labels.map(String).filter(x=>x.toLowerCase().includes(cropToken));
   const gem=await api('/api/gemini/vision',{method:'POST',body:JSON.stringify({crop,mimeType:'image/jpeg',imageData,labels:cropLabels})});
   const labelKnown=gem.label!=='unknown / not in supported catalogue',displayLabel=labelKnown?gem.label.replaceAll('___',' — ').replaceAll('_',' '):'No supported label matched';
   const block=document.createElement('article');block.className='result';block.style.marginTop='12px';block.innerHTML=`<div class="section-title"><div><div class="eyebrow">GEMINI VISION · ${esc(gem.model)}</div><div class="result-label" style="margin-top:6px">${esc(displayLabel)}</div></div><span class="confidence ${gem.uncertain?'limited':'good'}">${gem.uncertain?'UNCERTAIN':'SCREENING'}</span></div>${gem.visibleEvidence?.length?`<ul>${gem.visibleEvidence.map(x=>`<li style="margin:6px 0">${esc(x)}</li>`).join('')}</ul>`:''}<p class="rec-desc">Compared only with labels from the active PlantVillage classifier. This is not a confirmed diagnosis.</p>`;out.appendChild(block);
  }
 }catch(err){const prior=q('local-disease-result');const note=`<div class="banner warn" style="margin-top:12px"><strong>${useGemini&&prior?'Gemini vision did not run.':'Image analysis did not run.'}</strong> ${esc(err.message)} ${prior?'The local classifier result above is separate and remains available.':'No placeholder result was created.'}</div>`;out.insertAdjacentHTML('beforeend',note);toast(err.message,true)}finally{btn.disabled=false;btn.textContent=t('classify');}
}function softmax(a){const m=Math.max(...a),e=a.map(x=>Math.exp(x-m)),s=e.reduce((x,y)=>x+y,0);return e.map(x=>x/s)}
init();
